WITH recent_suppliers AS (SELECT * FROM suppliers WHERE city = 'Singapore'), rating_bucket_summary AS (SELECT CASE WHEN rating >= 4.2 THEN 'high' WHEN rating >= 1.8 THEN 'mid' ELSE 'low' END AS rating_bucket, city, ROUND(STDDEV(rating), 2) AS stddev_rating FROM recent_suppliers GROUP BY CASE WHEN rating >= 4.2 THEN 'high' WHEN rating >= 1.8 THEN 'mid' ELSE 'low' END, city) SELECT rating_bucket, city, stddev_rating FROM rating_bucket_summary
